<?php
namespace App\Http\Controllers\HR;use App\Http\Controllers\Controller;use App\Models\{Employee,AttendanceRecord,LeaveRequest,PayrollRun};class HrDashboardController extends Controller{public function __invoke(){ $p=auth()->user()->property_id;return view('hr.dashboard',['employees'=>Employee::where('property_id',$p)->count(),'active'=>Employee::where('property_id',$p)->where('status','active')->count(),'present'=>AttendanceRecord::where('property_id',$p)->whereDate('attendance_date',today())->where('status','present')->count(),'leave'=>LeaveRequest::where('property_id',$p)->where('status','pending')->count(),'payroll'=>PayrollRun::where('property_id',$p)->latest()->first()]);}}